const subject = String($json.subject || '').trim();
const body = String($json.body || '').trim();
const text = (subject + ' ' + body).toLowerCase();
const urgent = /(outage|security|breach|data loss|every user|all users)/.test(text);
const blocked = /(blocked|cannot|can't|fails|error|down)/.test(text);
const hasOwner = /@/.test(String($json.requester || ''));
const issues = [];
if (!subject) issues.push('missing subject');
if (!body) issues.push('missing body');
if (!hasOwner) issues.push('requester is not an email-shaped identifier');
return [{json:{
  diagnostic_version:'0.1.0',
  input_complete:issues.length===0,
  issues,
  suggested_priority:urgent?'urgent':(blocked?'high':'medium'),
  matched_signals:{urgent,blocked},
  next_step:'Replace the sample node with your intake, then compare these deterministic signals with your current routing rules.'
}}];
